    o.append(h2("2-1", "سامانه‌های اطلاعاتی چندنقشی و مدل مجوزدهی"))
    o.append(p("در سامانه‌ای که چند دستهٔ کاربر با اختیارات متفاوت دارد، کنترل دسترسی معمولاً با مدل «کنترل دسترسی مبتنی بر نقش» " + fn(1) + " پیاده می‌شود " + ref("Sandhu-P96") + ". در این مدل، مجوزها به نقش‌ها و نقش‌ها به کاربران منتسب می‌شوند. کوجیما سه نقش سراسری (مدیر، مربی، عضو) دارد؛ اما بسیاری از مجوزها به «زمینه» " + fn(2) + " نیز وابسته‌اند: مدیر فقط باشگاه‌های خودش را می‌بیند، مربی فقط شاگردان خودش را و عضو فقط داده‌های خودش را. بنابراین در عمل ترکیبی از RBAC و بررسی مالکیت رکورد به کار رفته است که در بخش ۳-۵ شرح داده می‌شود.", "first"))
    o.append('<div class="footnotes"></div><div class="fnline"><sup>1</sup> Role-Based Access Control (RBAC)</div><div class="fnline"><sup>2</sup> Context / tenant</div>')

    o.append(h2("2-2", "معماری برنامه‌های وب مدرن"))
    o.append(h3("2-2-1", "رندر سمت سرور و مؤلفه‌های سرور"))
    o.append(p("برنامه‌های تک‌صفحه‌ای " + fn(1) + " که در دههٔ ۲۰۱۰ رایج شدند، کل رابط کاربری را در مرورگر می‌سازند و داده را از API می‌گیرند. این رویکرد بار اولیهٔ سنگین و زمان انتظار بیشتری برای کاربر دارد. چارچوب‌های نسل جدید مانند Next.js با «رندر سمت سرور» " + fn(2) + " صفحهٔ HTML آماده را از سرور می‌فرستند و سپس در مرورگر تعاملی می‌کنند " + ref("Next-W25") + ". React از نسخهٔ ۱۹ مفهوم «مؤلفهٔ سرور» " + fn(3) + " را معرفی کرد: مؤلفه‌هایی که فقط روی سرور اجرا می‌شوند، مستقیماً به پایگاه داده دسترسی دارند و هیچ کد جاوااسکریپتی به مرورگر نمی‌فرستند " + ref("React-W25") + ". در کوجیما همهٔ صفحات پنل‌ها مؤلفهٔ سرورند و تنها بخش‌های تعاملی (فرم‌ها، ویرایشگر برنامه، تایمر، منوی موبایل) به‌صورت «جزیره‌های کلاینت» پیاده شده‌اند. این تصمیم حجم جاوااسکریپت ارسالی را کم و امنیت را بیشتر می‌کند، چون منطق دسترسی به داده هرگز مرورگر را ترک نمی‌کند.", "first"))
    o.append('<div class="footnotes"></div><div class="fnline"><sup>1</sup> Single-Page Application (SPA)</div><div class="fnline"><sup>2</sup> Server-Side Rendering (SSR)</div><div class="fnline"><sup>3</sup> React Server Components (RSC)</div>')
    o.append(h3("2-2-2", "مسیرهای API و معماری REST"))
    o.append(p("برای عملیات نوشتنی (ثبت‌نام، ساخت برنامه، پرداخت و…) از مسیرهای API با سبک REST استفاده شده است " + ref("Fielding-T00") + ": هر منبع یک URL دارد، افعال HTTP معنای استاندارد دارند (GET خواندن، POST ایجاد، PATCH ویرایش، DELETE حذف) و پاسخ‌ها با کد وضعیت مناسب (۲۰۰، ۲۰۱، ۴۰۰، ۴۰۱، ۴۰۳، ۴۰۴، ۴۰۹، ۴۲۹) همراه‌اند. جدول " + fa(2) + "-" + fa(1) + " قرارداد کدهای وضعیت در کوجیما را نشان می‌دهد.", "first"))
    o.append(table("قرارداد کدهای وضعیت HTTP در API کوجیما", ["کد", "معنا", "نمونهٔ کاربرد"], [
        ["۲۰۰ / ۲۰۱", "موفق / ایجاد شد", "دریافت فهرست شاگردان / ساخت برنامهٔ تمرینی"],
        ["۴۰۰", "دادهٔ نامعتبر", "ایمیل بدون @، ست منفی، تاریخ نامعتبر"],
        ["۴۰۱", "احراز هویت نشده", "کوکی نشست موجود نیست یا باطل شده"],
        ["۴۰۳", "مجاز نیست", "مربی می‌خواهد برنامهٔ مربی دیگر را ویرایش کند"],
        ["۴۰۴", "یافت نشد", "شناسهٔ باشگاه اشتباه"],
        ["۴۰۹", "تعارض", "ایمیل تکراری، تداخل جلسه، پرداخت تکراری"],
        ["۴۲۹", "درخواست بیش از حد", "بیش از ۲۰ تلاش ورود در دقیقه"],
    ], widths=["16%", "26%", "58%"]))

    o.append(h2("2-3", "پایگاه داده و نگاشت شیء–رابطه"))
    o.append(h3("2-3-1", "مدل رابطه‌ای و نرمال‌سازی"))
    o.append(p("داده‌های کوجیما ذاتاً رابطه‌ای‌اند: کاربر با باشگاه، باشگاه با طرح، طرح با اشتراک و اشتراک با پرداخت مرتبط است. مدل رابطه‌ای " + ref("Codd-P70") + " با کلیدهای خارجی و قیود یکتایی، یکپارچگی این روابط را در سطح پایگاه داده تضمین می‌کند. طرحوارهٔ سامانه تا سطح سوم نرمال " + fn(1) + " طراحی شده است؛ به‌جز چند مورد عمدی مانند ذخیرهٔ «قیمت پرداخت‌شده» در رکورد اشتراک، چون قیمت طرح ممکن است بعداً تغییر کند و سابقهٔ مالی باید ثابت بماند.", "first"))
    o.append('<div class="footnotes"></div><div class="fnline"><sup>1</sup> Third Normal Form (3NF)</div>')
    o.append(h3("2-3-2", "SQLite و libSQL"))
