    o.append('<div class="footnotes"></div><div class="fnline"><sup>1</sup> Replication</div>')
    o.append(h3("2-3-3", "Prisma به‌عنوان ORM"))
    o.append(p("نگاشت شیء–رابطه " + fn(1) + " لایه‌ای است که جدول‌ها را به اشیای زبان برنامه‌نویسی نگاشت می‌کند. Prisma طرحواره را در یک فایل اعلانی (" + code("schema.prisma") + ") تعریف می‌کند، از روی آن مهاجرت‌های SQL و یک کلاینت کاملاً نوع‌دار " + fn(2) + " تولید می‌کند " + ref("Prisma-W25") + ". مزیت اصلی برای این پروژه، کشف خطاهای دسترسی به داده در زمان کامپایل به‌جای زمان اجرا بود؛ برای مثال اگر فیلدی از مدل حذف شود، همهٔ کدهایی که از آن استفاده می‌کنند بلافاصله خطای نوع می‌دهند. شکل " + fa(2) + "-" + fa(1) + " جایگاه این لایه‌ها را نشان می‌دهد.", "first"))
