    o.append('<div class="footnotes"></div><div class="fnline"><sup>1</sup> JSON Web Token (JWT), RFC 7519</div><div class="fnline"><sup>2</sup> Claims</div><div class="fnline"><sup>3</sup> Cross-Site Scripting</div><div class="fnline"><sup>4</sup> Cross-Site Request Forgery</div>')
    o.append(h3("2-4-3", "محدودیت نرخ درخواست"))
    o.append(p("برای مقابله با حملات حدس گذرواژه و سوءاستفاده از API، تعداد درخواست هر کلاینت در بازهٔ زمانی مشخص محدود می‌شود. الگوریتم «پنجرهٔ ثابت» " + fn(1) + " ساده‌ترین روش است: برای هر کلید (مثلاً آدرس IP) شمارنده‌ای نگه داشته می‌شود که در پایان هر پنجره صفر می‌شود. کوجیما از این الگوریتم با دو سطل جداگانه برای مسیرهای احراز هویت (۲۰ درخواست در دقیقه) و سایر مسیرهای نوشتنی (۱۲۰ درخواست در دقیقه) استفاده می‌کند.", "first"))
    o.append('<div class="footnotes"></div><div class="fnline"><sup>1</sup> Fixed window</div>')

    o.append(h2("2-5", "پرداخت الکترونیک و خودتوانی عملیات"))
    o.append(p("در یکپارچه‌سازی با درگاه پرداخت، دو اصل اهمیت ویژه دارند. نخست، «خودتوانی» " + fn(1) + ": اگر درخواست پرداخت به هر دلیل تکرار شود (مثلاً کاربر دوبار کلیک کند یا شبکه قطع و وصل شود)، نباید دو پرداخت ثبت شود. راه‌حل استاندارد، همراه کردن هر درخواست با یک «کلید خودتوانی» یکتا و رد کردن کلید تکراری در سطح پایگاه داده است " + ref("Stripe-W25") + ". دوم، «تأیید سمت سرور»: نتیجهٔ پرداخت هرگز نباید بر اساس پارامترهای بازگشتی مرورگر پذیرفته شود؛ بلکه باید از طریق فراخوان برگشتی " + fn(2) + " امضاشدهٔ درگاه یا استعلام مستقیم تأیید شود. کوجیما هر دو اصل را با کلید خودتوانی یکتا در جدول پرداخت و امضای HMAC-SHA256 روی فراخوان برگشتی رعایت می‌کند.", "first"))
