    o.append('<div class="footnotes"></div><div class="fnline"><sup>1</sup> Headless browser</div>')

    o.append(h2("2-9", "جمع‌بندی فناوری‌های انتخاب‌شده"))
    o.append(p("جدول " + fa(2) + "-" + fa(2) + " فناوری‌های اصلی پروژه و دلیل انتخاب هر یک را خلاصه می‌کند. ملاک‌های انتخاب عبارت بودند از: بلوغ و پشتیبانی جامعه، نوع‌دار بودن، قابلیت اجرا بدون وابستگی به سرویس خارجی، و هزینهٔ صفر برای میزبانی در مقیاس کوچک.", "first"))
