        ["ORM", "Prisma", "۷", "طرحوارهٔ اعلانی، مهاجرت، کلاینت نوع‌دار"],
        ["پایگاه داده", "SQLite / libSQL (Turso)", "–", "بدون سرور در توسعه، میزبانی ابری بدون تغییر کد"],
